# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs, offset=-1):
    return [v + offset for v in xs[1:]]

# region: emit
def emit(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(sift(emit(fold(shape(raw)))))

