        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'total': 22, 'label': 'GAMMA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'total': 0, 'label': 'EMPTY'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 20, 'label': 'GAMMA'})
